function renderGameSelection(){const selected=$('#gameId')?.value||'',grid=$('#gamesGrid'),select=$('#gameId');if(grid){grid.innerHTML='';config.games.forEach(g=>{const image=window.KM_CARD_IMAGES?.games?.[String(g.id)],visual=image?`<img class="km-card-catalog-image" data-group-src="${esc(image)}" alt="" aria-hidden="true" width="96" height="96" decoding="async">`:`<span class="emoji" aria-hidden="true">${esc(g.icon||'🎮')}</span>`;grid.insertAdjacentHTML('beforeend',`<a class="game-card game-tile" href="#order" data-game="${g.id}" aria-label="عرض باقات ${esc(g.name)}"><span class="badge">متوفر الآن</span>${visual}<h3>${esc(g.name)}</h3><span class="btn">عرض الباقات ←</span></a>`)});window.loadBaseCardImageGroups?.(grid,12)}if(select){select.innerHTML='<option value="">اختر اللعبة</option>'+config.games.map(g=>`<option value="${g.id}">${esc(g.name)}</option>`).join('');if(config.games.some(g=>String(g.id)===String(selected)))select.value=selected}}
function gameQtyOptions(p){const q=p?.qty_values;let raw;if(Array.isArray(q))raw=q;else if(q&&typeof q==='object'){const lo=parseFlexibleAmount(q.min),hi=parseFlexibleAmount(q.max);if(!Number.isInteger(lo)||!Number.isInteger(hi)||lo<=0||hi<lo||hi-lo>20)return['1'];raw=Array.from({length:hi-lo+1},(_,i)=>lo+i)}else raw=[1];const seen=new Set(),values=raw.map(parseFlexibleAmount).filter(n=>Number.isFinite(n)&&n>0).map(n=>String(n)).filter(n=>{if(seen.has(n))return false;seen.add(n);return true}).slice(0,20);return values.length?values:['1']}
