function readKmProductParams(form,p){const out={};for(const [i,key] of (p?.params||[]).entries()){const el=i===0?form.querySelector('[name="player_id"]'):form.querySelector(`[data-km-param-index="${i}"]`),value=String(el?.value||'').trim();if(!value)throw Error('المعلومات غير صحيحة أو ناقصة، حاول مرة أخرى');out[String(key)]=value}return out}
function extractKmProducts(raw){const seen=new Set();function walk(v,d=0){if(d>8||v==null)return[];if(Array.isArray(v))return v.filter(x=>x&&typeof x==='object'&&x.id!=null);if(typeof v!=='object'||seen.has(v))return[];seen.add(v);for(const k of ['products','items','results','data','result','payload']){if(v[k]!=null){const a=walk(v[k],d+1);if(a.length)return a}}return[]}return walk(raw)}
let baseProductCache=null,baseProductCacheAt=0,baseProductInFlight=null;
window.getBaseCardProducts=async(force=false)=>{
  if(baseProductInFlight)return baseProductInFlight;
  const reuseFor=force?5000:15000;
  if(baseProductCache&&Date.now()-baseProductCacheAt<reuseFor)return baseProductCache;
  const task=(async()=>{const r=await sb.functions.invoke(KM_PROXY,{body:{action:'products'}});if(r.error||r.data?.error)throw r.error||new Error(r.data?.error||'catalog unavailable');const rows=extractKmProducts(r.data);if(!rows.length)throw new Error('catalog empty');baseProductCache=rows;baseProductCacheAt=Date.now();return rows})();
  baseProductInFlight=task;try{return await task}finally{if(baseProductInFlight===task)baseProductInFlight=null}
};
async function loadKmGameCatalog(){
  let live=[];try{live=await window.getBaseCardProducts(false)}catch(_){}
  const local=(typeof LOCAL_KM_GAME_CATALOG!=='undefined'?LOCAL_KM_GAME_CATALOG:[]);
  const merged=new Map(local.filter(p=>p&&p.id!=null).map(p=>[Number(p.id),p]));
  live.forEach(p=>{if(p&&p.id!=null)merged.set(Number(p.id),p)});
  kmGameCatalog=[...merged.values()].map(normalizeKmGameProduct).filter(p=>{
    if(!p)return false;const id=Number(p.id),cat=String(p.category_name||'').trim();
    if(cat==='FREE FIRE GLOBAL')return KM_FREE_FIRE_IDS.includes(id);
    if(cat.toUpperCase()==='PUBG GLOBAL')return true;
    return KM_GAME_CATEGORIES.has(cat)&&KM_APPROVED_GAME_IDS.has(id);
  });
  if(!kmGameCatalog.some(p=>Number(p.id)===276))kmGameCatalog.push({id:276,name:'باقة 110 جوهرة (100 + 10 بونص)',sale_price_syp:kmSaleFor(276,null,1),category_name:'FREE FIRE GLOBAL',params:['أيدي اللاعب'],available:true,product_type:'package'});
  if(!kmGameCatalog.some(p=>String(p.category_name||'').trim().toUpperCase()==='PUBG GLOBAL'))kmGameCatalog.push(...KM_PUBG_GLOBAL_FALLBACK);
  const known=new Set(config.games.flatMap(gameCategories));
  for(const def of KM_GAME_DEFS){if(def.categories.some(c=>kmGameCatalog.some(p=>String(p.category_name||'').trim()===c&&p.available!==false))&&!def.categories.some(c=>known.has(c))){config.games.push({id:def.id,name:def.name,description:'اختر الباقة المتاحة للشحن',icon:def.icon,visible:true,km_categories:def.categories});def.categories.forEach(c=>known.add(c))}}
  renderGameSelection();if($('#gameId')?.value)fillPackages();else{updateKmQuantityField(null);renderKmProductParams(null)}syncCustomerNameField();
}

let kmAvailabilityRefreshRunning=false,kmAvailabilityPollingStarted=false;
async function refreshKmAvailability(){
  if(kmAvailabilityRefreshRunning)return;
  kmAvailabilityRefreshRunning=true;
  try{
    const rows=await window.getBaseCardProducts(true),latest=new Map(rows.map(p=>[Number(p.id),p]));
    if(!rows.length)return;
    let changed=false;
    kmGameCatalog=kmGameCatalog.map(p=>{const live=latest.get(Number(p.id));if(!live)return p;const availabilityChanged=typeof live.available==='boolean'&&p.available!==live.available,pricesChanged=!!live.sale_prices_syp&&JSON.stringify(live.sale_prices_syp)!==JSON.stringify(p.sale_prices_syp||{}),priceChanged=live.sale_price_syp!==undefined&&Number(live.sale_price_syp)!==Number(p.sale_price_syp);if(!availabilityChanged&&!pricesChanged&&!priceChanged)return p;changed=true;return normalizeKmGameProduct({...p,...live})});
    if(!changed)return;
    const game=config.games.find(g=>Number(g.id)===Number($('#gameId')?.value));
    if(!isKmGame(game))return;
    const selected=String($('#packageId')?.value||'');fillPackages();
    if(selected){const button=[...document.querySelectorAll('#packagesGrid .package-card')].find(x=>String(x.dataset.packageId)===selected&&!x.disabled);if(button){$('#packageId').value=selected;button.classList.add('selected');updatePrice()}}
  }catch(_){}finally{kmAvailabilityRefreshRunning=false}
}
function startKmAvailabilityPolling(){if(kmAvailabilityPollingStarted)return;kmAvailabilityPollingStarted=true;setInterval(()=>{if(document.visibilityState==='visible')refreshKmAvailability()},60000);document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')refreshKmAvailability()});window.addEventListener('focus',refreshKmAvailability)}

function kmPackageFor(id){return kmGameCatalog.find(p=>Number(p.id)===Number(id));}
