$('#googleLogin').addEventListener('click',e=>{e.preventDefault();signIn()});$('#logoutUser').addEventListener('click',async()=>{await sb.auth.signOut();location.reload()});sb.auth.onAuthStateChange(()=>setTimeout(loadUser,0));
function fillPackages(){const id=Number($('#gameId').value),grid=$('#packagesGrid'),hidden=$('#packageId');hidden.value='';hidden.disabled=false;updateKmQuantityField(null);renderKmProductParams(null);if(!id){grid.innerHTML='<div class="packages-empty">اختر اللعبة أولًا</div>';updatePrice();return}const game=config.games.find(g=>Number(g.id)===id),categories=gameCategories(game),isProviderGame=categories.length>0;const kmPacks=isProviderGame?kmGameCatalog.filter(p=>categories.includes(String(p.category_name||'').trim())&&(String(p.category_name||'').trim()!=='FREE FIRE GLOBAL'||KM_FREE_FIRE_IDS.includes(Number(p.id)))):[];const packs=isProviderGame?kmPacks:config.packages.filter(p=>Number(p.game_id)===id);grid.innerHTML=packs.length?packs.map(p=>{const unavailable=isProviderGame&&p.available===false,quantityOptions=gameQtyOptions(p),priceValue=isProviderGame?kmSaleFor(p.id,null,quantityOptions[0]||1,p):null,unpriced=isProviderGame&&(priceValue===null||priceValue===undefined),blocked=unavailable||unpriced,price=unavailable?'غير متاح':unpriced?'السعر غير مضبوط بعد':isProviderGame?`${quantityOptions.length>1?'يبدأ من ':''}${Number(priceValue).toLocaleString('ar-SY')} ل.س جديدة`:`${esc(p.price_amount??p.price)} ${p.currency==='SYP'?'ل.س جديدة':'$'}`;return `<button type="button" class="package-card${unavailable?' package-unavailable':''}" data-package-id="${p.id}" data-km-product="${isProviderGame?'1':''}" ${blocked?'disabled aria-disabled="true"':''}><span class="package-icon">✦</span><span class="package-name">${esc(p.name)}</span><span class="package-price">${price}</span><span class="package-check">✓</span></button>`}).join(''):'<div class="packages-empty">لا توجد باقات متاحة لهذه اللعبة</div>';updatePrice()}
function updatePrice(){const p=kmPackageFor($('#packageId').value)||config.packages.find(x=>x.id===Number($('#packageId').value)),isProviderGame=!!p?.category_name,q=p?currentKmQuantity(p):'1',sale=isProviderGame?kmSaleFor(p.id,null,q,p):null;$('#orderPrice').textContent=p?(isProviderGame?(sale!=null?`سيتم خصم ${Number(sale).toLocaleString('ar-SY')} ل.س جديدة من محفظتك عند إرسال الطلب.`:'يجب تحديد سعر البيع من لوحة الإدارة أولًا.'):`سيتم خصم ${money(p.price_amount??p.price,p.currency)} من محفظتك عند إرسال الطلب.`):'سيتم خصم قيمة الباقة من محفظتك عند إرسال الطلب.';if($('#orderPriceUsd'))$('#orderPriceUsd').textContent=''}
function syncCustomerNameField(){const game=config.games.find(x=>Number(x.id)===Number($('#gameId')?.value));const isFreeFire=/free\s*fire|فري\s*فاير/i.test(String(game?.name||'')),hideName=isFreeFire||Array.isArray(game?.km_categories);const field=$('#customerNameField'),input=$('[name="customer_name"]');if(field&&input){field.hidden=hideName;field.style.display=hideName?'none':'';field.setAttribute('aria-hidden',hideName?'true':'false');input.required=!hideName;if(hideName){input.value='';input.setCustomValidity('')}}}
$('#gameId').addEventListener('change',()=>{fillPackages();syncCustomerNameField()});document.addEventListener('click',e=>{const p=e.target.closest('.package-card');if(p&&!p.disabled){if($('#orderForm'))delete $('#orderForm').dataset.orderUuid;$('#packageId').value=p.dataset.packageId;$('#packageId').disabled=false;document.querySelectorAll('.package-card').forEach(x=>x.classList.toggle('selected',x===p));const product=kmPackageFor(p.dataset.packageId);updateKmQuantityField(product);renderKmProductParams(product);updatePrice()}});
function orderNo(){return `BC-${new Date().toISOString().slice(0,10).replaceAll('-','')}-${Math.floor(100000+Math.random()*899999)}`}
const FREE_FIRE_KM_PRODUCTS=[{match:/110/,id:276},{match:/210\s*\+\s*21|231/,id:277},{match:/583/,id:14},{match:/1166|1188/,id:20},{match:/2398|2420/,id:23},{match:/الأسبوعية|weekly/i,id:27},{match:/الشهرية|monthly/i,id:31},{match:/booyah|pass/i,id:34}];
function freeFireKmProductId(pack){const name=String(pack?.name||'');return FREE_FIRE_KM_PRODUCTS.find(x=>x.match.test(name))?.id||null}
async function submitFreeFireToKmCard(pack,playerId){const productId=freeFireKmProductId(pack);if(!productId)throw Error('هذه الباقة غير متاحة حاليًا');const cat=await sb.functions.invoke('kmcard-proxy',{body:{action:'products'}});if(cat.error)throw cat.error;const product=(cat.data?.products||cat.data||[]).find(x=>Number(x.id)===productId);if(!product)throw Error('منتج الشحن غير متاح حاليًا');const key=String(product.params?.[0]||'ايدي اللاعب');const r=await sb.functions.invoke('kmcard-proxy',{body:{action:'order',product:{id:productId,name:product.name,category_name:product.category_name,params:product.params||[]},qty:1,params:{[key]:String(playerId).trim()},idempotency_key:crypto.randomUUID()}});if(r.error)throw r.error;if(r.data?.error)throw Error(r.data.error);return r.data}
function rememberRecentOrder(x){if(!x?.order_number)return;const a=JSON.parse(localStorage.getItem('basecard_recent_km_orders')||'[]');a.unshift({...x,created_at:x.created_at||new Date().toISOString()});localStorage.setItem('basecard_recent_km_orders',JSON.stringify(a.filter(y=>y.order_number).slice(0,30)))}
async function submitKmGameToKmCard(product,params,idempotencyKey,qty='1',quotedSale=null){if(!product)throw Error('الباقة غير متاحة حاليًا');const r=await sb.functions.invoke('kmcard-proxy',{body:{action:'order',product:{id:Number(product.id),name:product.name,category_name:product.category_name,params:product.params||[]},qty:String(qty),params:params||{},quoted_sale_price_syp:quotedSale==null?undefined:String(quotedSale),idempotency_key:idempotencyKey}});if(r.data)applyWalletSnapshot(r.data);if(r.error){window.refreshBaseCardWallet?.(true);throw r.error}if(r.data?.error){window.refreshBaseCardWallet?.(true);throw Error(r.data.error)}const st=String(r.data?.status||'').toLowerCase(),ps=String(r.data?.provider_status||'').toLowerCase();if(['reject','rejected','refunded'].includes(st)||['reject','rejected','refunded'].includes(ps)){window.refreshBaseCardWallet?.(true);throw Error('تم رفض الطلب، وأُعيد المبلغ إلى محفظتك')}return r.data}

