$('#topupForm').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target),currency=f.get('currency'),amount=parseFlexibleAmount(f.get('amount'));const paymentNumber=String(f.get('payment_number')||'').trim().replace(/[٠-٩]/g,d=>String('٠١٢٣٤٥٦٧٨٩'.indexOf(d))).replace(/[۰-۹]/g,d=>String('۰۱۲۳۴۵۶۷۸۹'.indexOf(d)));if(!/^[0-9]+$/.test(paymentNumber)){const msg='رقم عملية شام كاش يجب أن يحتوي أرقامًا فقط.';flashMessage(msg,'error');return show('#topupAlert',msg,'error')}f.set('payment_number',paymentNumber);if(!Number.isFinite(amount)||amount<=0||amount>1000000000){const msg='المبلغ المدخل غير صحيح، راجع المبلغ ورقم عملية شام كاش.';flashMessage(msg,'error');return show('#topupAlert',msg,'error')}if((currency==='USD'&&amount<5)||(currency==='SYP'&&amount<500)){const msg=currency==='USD'?'الحد الأدنى للشحن 5 دولارات':'الحد الأدنى للشحن 500 ليرة سورية';flashMessage(msg,'error');return show('#topupAlert',msg,'error')}const btn=e.target.querySelector('button');btn.disabled=true;try{const {data:ud}=await sb.auth.getUser();if(!ud.user)throw Error('سجّل الدخول أولًا لإرسال طلب تعبئة النقاط');const r=await sb.rpc('submit_topup_request',{p_amount:amount,p_currency:currency,p_payment_number:f.get('payment_number'),p_receipt_path:null});if(r.error)throw r.error;const msg='تم إرسال طلب شراء النقاط بنجاح، وستتم مراجعة طلبك يدويًا ويُضاف الرصيد بعد قبوله في أقرب وقت ممكن.';flashMessage(msg,'success');show('#topupAlert',msg,'success');e.target.reset();updateUsdTopupPreview()}catch(err){const raw=String(err?.message||err||'');const msg=/duplicate|مكرر|payment/i.test(raw)?'رقم عملية شام كاش مستخدم مسبقًا، راجع الرقم وأرسل عملية صحيحة.':/تسجيل الدخول|auth|JWT/i.test(raw)?'سجّل الدخول أولًا لإرسال طلب تعبئة النقاط.':'تعذر إرسال طلب تعبئة النقاط، راجع المبلغ ورقم عملية شام كاش وحاول مرة أخرى.';flashMessage(msg,'error');show('#topupAlert',msg,'error')}finally{btn.disabled=false}});
function trackMoney(pkg){if(!pkg)return '—';if(pkg.price_amount!=null)return money(pkg.price_amount,pkg.currency||'SYP');return pkg.price?esc(pkg.price):'—'}function renderTrackGuest(){const a=$('#trackAlert');if(a)show('#trackAlert','سجّل الدخول عبر Google لعرض طلبات آخر 24 ساعة','error');if($('#trackResult'))$('#trackResult').innerHTML='<h3>طلبات آخر 24 ساعة</h3><p class="muted">سجّل الدخول أولًا، وستظهر طلباتك تلقائيًا هنا.</p>'}async function readRecentOrdersFallback(){const end=new Date(),start=new Date(end.getTime()-86400000),startIso=start.toISOString(),endIso=end.toISOString();const [k,o]=await Promise.all([sb.from('kmcard_orders').select('order_number,status,provider_status,category_name,product_name,charged_syp,created_at,updated_at').gte('created_at',startIso).lt('created_at',endIso).order('created_at',{ascending:false}),sb.from('orders').select('order_number,status,game_id,package_id,player_id,created_at,updated_at').gte('created_at',startIso).lt('created_at',endIso).order('created_at',{ascending:false})]);if(k.error&&o.error)throw k.error;const km=(k.data||[]).map(x=>({...x,source:'kmcard',title:String(x.category_name||'خدمة الشحن').replace(/KM\s*Card|كيم\s*كارد/ig,'خدمة الشحن'),package_name:x.product_name,amount:x.charged_syp,currency:'SYP'}));const legacy=(o.data||[]).map(x=>{const p=(config.packages||[]).find(v=>Number(v.id)===Number(x.package_id));const g=(config.games||[]).find(v=>Number(v.id)===Number(x.game_id));return {...x,source:'legacy',title:g?.name||'طلب شحن',package_name:p?.name||'—',target_id:x.player_id||null,amount:Number(p?.price_amount??p?.price??0),currency:p?.currency||'SYP'}});return [...km,...legacy].sort((a,b)=>new Date(b.created_at)-new Date(a.created_at))}
let trackLoading=false,trackRequestId=0,trackAutoTimer=null;
function stopTrackAutoRefresh(){if(trackAutoTimer){clearInterval(trackAutoTimer);trackAutoTimer=null}}
function startTrackAutoRefresh(){stopTrackAutoRefresh();trackAutoTimer=setInterval(()=>{if(location.hash.slice(1)==='track'&&document.visibilityState==='visible'&&!trackLoading)loadTrackOrders();else if(location.hash.slice(1)!=='track')stopTrackAutoRefresh()},30000)}
function renderTrackingRows(rows){const labels={pending:'قيد الانتظار',processing:'قيد المعالجة',completed:'مكتمل',accepted:'مكتمل',accept:'مكتمل',rejected:'مرفوض',reject:'مرفوض',refunded:'مرفوض — تمت إعادة الرصيد',wait:'قيد الانتظار'};if(!rows.length){$('#trackResult').innerHTML='<h3>طلبات آخر 24 ساعة</h3><p class="muted">لا توجد طلبات لك اليوم.</p>';return}$('#trackResult').innerHTML=`<h3>طلبات آخر 24 ساعة <small class="muted">(${rows.length})</small></h3><div class="track-orders">${rows.map(d=>{const provider=String(d.provider_status||'').toLowerCase();const st=provider==='wait'?'wait':provider==='accept'?'accept':provider==='reject'?'reject':String(d.status||'').toLowerCase();const shown=labels[st]||'قيد المعالجة';return `<article class="track-order"><div><b>${esc(d.order_number||'—')}</b><span class="status ${['completed','accepted','accept'].includes(st)?'completed':['rejected','reject','refunded'].includes(st)?'rejected':''}">${shown}</span></div><p>${esc(String(d.title||'طلب شحن').replace(/KM\s*Card|كيم\s*كارد/ig,'خدمة الشحن'))} — ${esc(String(d.package_name||'—').replace(/KM\s*Card|كيم\s*كارد/ig,'خدمة الشحن'))}</p>${d.target_id?`<p class="track-order-target"><b>معرّف اللاعب/المستخدم:</b> <span dir="ltr">${esc(String(d.target_id))}</span></p>`:''}<small>المبلغ: ${money(d.amount||0,d.currency||'SYP')}<br>التاريخ: ${new Date(d.created_at).toLocaleString('ar-SY',{timeZone:'Asia/Damascus'})}${d.provider_status?`<br>حالة المزود: ${esc(d.provider_status)}`:''}</small></article>`}).join('')}</div>`}
async function refreshKmOrderStatuses(rows){const pending=rows.filter(x=>x.source==='kmcard'&&x.order_number&&['pending','processing','wait'].includes(String(x.status||'').toLowerCase()));const recent=JSON.parse(localStorage.getItem('basecard_recent_km_orders')||'[]');let walletMayHaveBeenRefunded=false;await Promise.all(pending.map(async x=>{const before=String(x.status||'').toLowerCase();const c=await Promise.race([sb.functions.invoke(KM_PROXY,{body:{action:'check_number',order_number:x.order_number}}),new Promise(resolve=>setTimeout(()=>resolve(null),6000))]).catch(()=>null);const st=c?.data?.status;if(st){x.status=st;x.provider_status=st;const s=String(st).toLowerCase();if(/^(reject|rejected|refunded)$/.test(s)&&!/^(reject|rejected|refunded)$/.test(before))walletMayHaveBeenRefunded=true;const i=recent.findIndex(y=>y.order_number===x.order_number);if(i>=0){recent[i].status=st;recent[i].provider_status=st}}}));announceFinalOrderUpdates(rows);localStorage.setItem('basecard_recent_km_orders',JSON.stringify(recent));renderTrackingRows(rows);if(walletMayHaveBeenRefunded)await window.refreshBaseCardWallet?.(true)}

function announceFinalOrderUpdates(rows){let recent=[],seen=[];try{recent=JSON.parse(localStorage.getItem('basecard_recent_km_orders')||'[]')}catch(_){}const seenKey=`basecard_order_notices_${currentUser?.id||'guest'}`;try{seen=JSON.parse(localStorage.getItem(seenKey)||'[]')}catch(_){}let notice=null;const stateOf=x=>{const s=String(x?.provider_status||x?.status||'').toLowerCase();if(['accept','accepted','completed'].includes(s))return'completed';if(['reject','rejected','refunded'].includes(s))return'rejected';return''};for(const x of rows||[]){if(!x?.order_number)continue;const prior=recent.find(y=>String(y.order_number)===String(x.order_number));const nextState=stateOf(x),previousState=stateOf(prior);if(prior&&nextState&&!previousState&&!notice){const key=`${x.order_number}:${nextState}`;if(!seen.includes(key)){seen.push(key);const title=String(prior.title||x.title||x.category_name||'');const game=/free\s*fire|فري\s*فاير/i.test(title)?'فري فاير':/pubg|ببجي/i.test(title)?'ببجي موبايل':title||'طلب الشحن';notice={state:nextState,text:nextState==='completed'?`طلبك مكتمل في ${game} ✅ ${prior.package_name||x.package_name||'باقة الشحن'}`:`تعذر إكمال ${game} — ${prior.package_name||x.package_name||'باقة الشحن'} ❌ وتمت إعادة الرصيد إلى محفظتك.`}}}if(prior){prior.status=x.status||prior.status;prior.provider_status=x.provider_status||prior.provider_status;prior.updated_at=x.updated_at||prior.updated_at}}localStorage.setItem('basecard_recent_km_orders',JSON.stringify(recent.slice(0,30)));localStorage.setItem(seenKey,JSON.stringify(seen.slice(-100)));}
function normalizeRecentOrders(data){if(typeof data==='string'){try{return normalizeRecentOrders(JSON.parse(data))}catch(_){return null}}if(Array.isArray(data)){if(!data.length||data.some(x=>x&&typeof x==='object'&&('created_at'in x||'order_number'in x)))return data;if(data.length===1)return normalizeRecentOrders(data[0]);return null}if(data&&typeof data==='object'){if(Array.isArray(data.orders))return data.orders;if(Array.isArray(data.my_recent_orders_v1))return data.my_recent_orders_v1;for(const value of Object.values(data)){const rows=normalizeRecentOrders(value);if(rows)return rows}}return null}
function trackWithTimeout(promise,ms){let timer;return Promise.race([promise,new Promise((_,reject)=>{timer=setTimeout(()=>reject(new Error('track-timeout')),ms)})]).finally(()=>clearTimeout(timer))}
async function loadTrackOrders(force=false){
 if(!$('#trackResult'))return;
 if(trackLoading&&!force)return;
 const run=++trackRequestId;trackLoading=true;$('#trackAlert')?.classList.add('hidden');$('#trackResult').innerHTML='<h3>طلبات آخر 24 ساعة</h3><p class="muted">جارٍ تحميل طلباتك...</p>';
 try{
  if(!currentUser){const auth=await Promise.race([sb.auth.getUser(),new Promise(resolve=>setTimeout(()=>resolve({data:{user:null}}),5000))]);currentUser=auth?.data?.user||null}
  if(!currentUser){renderTrackGuest();return}
  let rows=null,loaded=false;
  try{const rpc=await trackWithTimeout(sb.rpc('my_recent_orders_v1'),4000);const normalized=!rpc.error?normalizeRecentOrders(rpc.data):null;if(normalized){rows=normalized;loaded=true}}catch(_){}
  if(!loaded){try{const data=await trackWithTimeout(sb.functions.invoke(KM_PROXY,{body:{action:'my_orders'}}),4000);if(!data.error&&!data.data?.error&&Array.isArray(data.data?.orders)){rows=data.data.orders;loaded=true}}catch(_){}}
  if(!loaded)rows=await trackWithTimeout(readRecentOrdersFallback(),4000);
  const now=Date.now(),cutoff=now-86400000;
  rows=rows.filter(x=>{const created=Date.parse(x.created_at||'');return Number.isFinite(created)&&created>=cutoff&&created<=now});
  const recent=JSON.parse(localStorage.getItem('basecard_recent_km_orders')||'[]').filter(x=>{const created=Date.parse(x.created_at||'');return Number.isFinite(created)&&created>=cutoff&&created<=now});
  recent.forEach(x=>{if(x.order_number&&!rows.some(y=>y.order_number===x.order_number))rows.push(x)});
  rows.sort((a,b)=>new Date(b.created_at)-new Date(a.created_at));
  if(run!==trackRequestId)return;
  announceFinalOrderUpdates(rows);renderTrackingRows(rows);trackLoading=false;
  if(rows.some(x=>x.source==='kmcard'&&x.order_number&&['pending','processing','wait'].includes(String(x.status||'').toLowerCase())))refreshKmOrderStatuses(rows)
 }catch(_){if(run===trackRequestId){trackLoading=false;show('#trackAlert','تعذر تحميل طلبات آخر 24 ساعة حاليًا','error');$('#trackResult').innerHTML='<h3>طلبات آخر 24 ساعة</h3><p class="muted">لم نتمكن من تحميل الطلبات. أعد فتح القسم للمحاولة مرة أخرى.</p>'}}
 finally{if(run===trackRequestId)trackLoading=false}
}
