function customerPushKeyBytes(value){const b64=value.replace(/-/g,'+').replace(/_/g,'/'),padded=b64+'='.repeat((4-b64.length%4)%4);return Uint8Array.from(atob(padded),c=>c.charCodeAt(0))}
const CUSTOMER_PUSH_PREF_KEY='basecard_customer_push_prompt_choice_v1',CUSTOMER_PUSH_PENDING_KEY='basecard_customer_push_pending_v1';let pendingCustomerPushMemory=null;
function customerPushSupported(){return 'serviceWorker'in navigator&&'PushManager'in window&&'Notification'in window}
function customerPushPref(){try{return localStorage.getItem(CUSTOMER_PUSH_PREF_KEY)||''}catch(_){return''}}
function setCustomerPushPref(value){try{localStorage.setItem(CUSTOMER_PUSH_PREF_KEY,value)}catch(_){}}
