async function createCustomerPushSubscription(){
 let permission=Notification.permission;
 try{if(permission!=='granted')permission=await Notification.requestPermission()}catch(err){err.pushPhase='permission';throw err}
 if(permission!=='granted'){const err=new Error(permission==='denied'?'permission_denied':'permission_not_granted');err.pushPhase='permission';throw err}
 let reg;try{reg=await Promise.race([navigator.serviceWorker.ready,new Promise((_,reject)=>setTimeout(()=>reject(new Error('serviceworker_timeout')),10000))])}catch(err){err.pushPhase='serviceworker';throw err}
 let sub;try{sub=await reg.pushManager.getSubscription();if(!sub)sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:customerPushKeyBytes(CUSTOMER_PUSH_PUBLIC_KEY)});const keys=sub.toJSON().keys||{};if(!keys.p256dh||!keys.auth)throw new Error('subscription_keys_missing');return{endpoint:sub.endpoint,p256dh:keys.p256dh,auth:keys.auth}}catch(err){err.pushPhase='subscription';throw err}
}
async function persistCustomerPushSubscription(value){if(currentUser){const r=await sb.rpc('save_customer_push_subscription',{p_endpoint:value.endpoint,p_p256dh:value.p256dh,p_auth:value.auth});if(r.error){r.error.pushPhase='saving';throw r.error}return'linked'}pendingCustomerPushMemory=value;try{localStorage.setItem(CUSTOMER_PUSH_PENDING_KEY,JSON.stringify(value))}catch(_){}return'pending'}
async function syncPendingCustomerPushSubscription(){if(!currentUser)return false;let value=pendingCustomerPushMemory;try{if(!value)value=JSON.parse(localStorage.getItem(CUSTOMER_PUSH_PENDING_KEY)||'null')}catch(_){}if(!value?.endpoint||!value?.p256dh||!value?.auth)return false;try{const r=await sb.rpc('save_customer_push_subscription',{p_endpoint:value.endpoint,p_p256dh:value.p256dh,p_auth:value.auth});if(r.error){console.warn('pending customer push link failed',r.error);return false}pendingCustomerPushMemory=null;try{localStorage.removeItem(CUSTOMER_PUSH_PENDING_KEY)}catch(_){}return true}catch(err){console.warn('pending customer push link failed',err);return false}}
async function showCustomerPushConsent(){const modal=$('#customerPushConsent');if(!modal||!customerPushSupported()||customerPushPref()||!navigator.onLine||!$('#offlineOverlay')?.classList.contains('hidden'))return;try{const reg=await navigator.serviceWorker.getRegistration(location.href),sub=await reg?.pushManager.getSubscription();if(sub)return}catch(_){}modal.classList.remove('hidden');document.body.classList.add('push-consent-open');setTimeout(()=>$('#customerPushConsentAllow')?.focus(),80)}
async function acceptCustomerPushConsent(){const btn=$('#customerPushConsentAllow'),status=$('#customerPushConsentStatus');if(!btn||btn.disabled)return;btn.disabled=true;status?.classList.remove('hidden');if(status)status.textContent='جارٍ تفعيل الإشعارات…';setCustomerPushPref('allow');try{if(!customerPushSupported())throw Object.assign(new Error('unsupported'),{pushPhase:'permission'});const value=await createCustomerPushSubscription(),result=await persistCustomerPushSubscription(value);if(status)status.textContent=result==='linked'?'تم تفعيل الإشعارات على هذا الجهاز.':'تم السماح؛ سجّل الدخول لربطها بإشعارات حسابك.';if(currentUser)await loadCustomerPushStatus();setTimeout(closeCustomerPushConsent,900)}catch(err){console.error('customer push consent failed',err);if(status)status.textContent=err.pushPhase==='permission'&&'Notification'in window&&Notification.permission==='denied'?'إشعارات الموقع محظورة من المتصفح؛ اسمح بها من إعداداته ثم فعّلها من المحفظة.':err.pushPhase==='serviceworker'?'تعذر تجهيز خدمة الإشعارات؛ أغلق التطبيق وافتحه ثم حاول مجددًا.':err.pushPhase==='subscription'?'تعذر تسجيل هذا الجهاز؛ يبقى زر المحفظة متاحًا للمحاولة لاحقًا.':err.pushPhase==='saving'?'تعذر ربط الإشعارات بالحساب؛ جرّب زر المحفظة بعد تسجيل الدخول.':'هذا المتصفح لا يدعم إشعارات الهاتف.'}finally{btn.disabled=false}}
$('#customerPushConsentAllow')?.addEventListener('click',acceptCustomerPushConsent);
$('#customerPushConsentDeny')?.addEventListener('click',()=>{setCustomerPushPref('declined');closeCustomerPushConsent()});
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#customerPushConsent')?.classList.contains('hidden'))$('#customerPushConsentDeny')?.click()});
setTimeout(showCustomerPushConsent,450);
async function loadCustomerPushStatus(){const box=$('#customerPushStatus'),btn=$('#customerPushToggle');if(!box||!btn)return;if(!currentUser){box.textContent='سجّل الدخول أولًا لتفعيل إشعارات طلباتك.';btn.disabled=true;return}if(!('serviceWorker'in navigator)||!('PushManager'in window)||!('Notification'in window)){box.textContent='هذا المتصفح لا يدعم إشعارات الموقع.';btn.disabled=true;return}if(Notification.permission==='denied'){btn.disabled=false;btn.dataset.enabled='0';btn.textContent='تفعيل إشعارات الطلبات';box.textContent='الإشعارات محظورة من المتصفح؛ اسمح بها من إعدادات الموقع ثم أعد التفعيل.';return}btn.disabled=false;try{const reg=await navigator.serviceWorker.getRegistration(location.href)||await navigator.serviceWorker.register('./sw.js',{scope:'./'}),sub=await reg.pushManager.getSubscription();if(!sub){btn.dataset.enabled='0';btn.textContent='تفعيل إشعارات الطلبات';box.textContent='الإشعارات غير مفعّلة لهذا الجهاز.';return}const r=await sb.rpc('customer_push_subscription_status',{p_endpoint:sub.endpoint});if(r.error){btn.dataset.enabled='0';btn.textContent='إعادة تفعيل الإشعارات';box.textContent='تعذر التحقق من ربط الإشعارات بالحساب؛ اضغط لإعادة الربط.';return}const enabled=r.data===true;btn.dataset.enabled=enabled?'1':'0';btn.textContent=enabled?'إيقاف إشعارات الطلبات':'تفعيل إشعارات الطلبات';box.textContent=enabled?'إشعارات طلباتك مفعّلة على هذا الجهاز.':'الإشعارات غير مفعّلة لهذا الحساب على هذا الجهاز.'}catch(_){box.textContent='تعذر التحقق من حالة الإشعارات. حاول مجددًا.'}}
async function toggleCustomerPush(){
 const box=$('#customerPushStatus'),btn=$('#customerPushToggle');
 if(!box||!btn)return;
 if(!currentUser){box.textContent='سجّل الدخول أولًا لتفعيل إشعارات طلباتك.';return}
 btn.disabled=true;let phase='permission',refreshStatus=false;
 try{
  if(!customerPushSupported())throw new Error('unsupported');
  if(btn.dataset.enabled==='1'){
   phase='disable';const reg=await navigator.serviceWorker.getRegistration(location.href),sub=await reg?.pushManager.getSubscription();
   if(!sub)throw new Error('subscription_missing');
   const r=await sb.rpc('delete_customer_push_subscription',{p_endpoint:sub.endpoint});if(r.error)throw r.error;
   setCustomerPushPref('declined');box.textContent='تم إيقاف إشعارات الطلبات لهذا الحساب.';refreshStatus=true;return;
  }
  const value=await createCustomerPushSubscription();phase='saving';
  await persistCustomerPushSubscription(value);setCustomerPushPref('allow');
  box.textContent='تم تفعيل الإشعارات ✅ ستصلك نتائج الطلبات الجديدة على هذا الجهاز.';refreshStatus=true;
 }catch(err){
  phase=err.pushPhase||phase;console.error('customer push activation failed',phase,err);
  box.textContent=phase==='permission'&&'Notification'in window&&Notification.permission==='denied'?'إشعارات المتصفح محظورة؛ اسمح بها من إعدادات الموقع ثم أعد التفعيل.':phase==='serviceworker'?'تعذر تشغيل خدمة الإشعارات؛ أغلق التطبيق وافتحه ثم حاول مجددًا.':phase==='subscription'?'سمحت بالإشعارات لكن تعذر تسجيل هذا الجهاز؛ اضغط للتفعيل مرة أخرى.':phase==='saving'?'تعذر ربط الإشعارات بالحساب؛ سجّل الدخول مجددًا ثم حاول.':phase==='disable'?'تعذر إيقاف إشعارات هذا الجهاز؛ حاول مرة أخرى.':'لم يكتمل تفعيل الإشعارات؛ حاول مجددًا.';
 }finally{btn.disabled=false;if(refreshStatus)await loadCustomerPushStatus()}
}
$('#customerPushToggle')?.addEventListener('click',toggleCustomerPush);



window.refreshBaseCardWallet=(force=false)=>loadWallet(force);window.refreshBaseCardTrack=()=>loadTrackOrders(true);
